      "ballot_id": "B002",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten"
      ],
      "assessment": {
        "nobel_worthiness": "AdS/CFT is a striking, durable connection between gauge theories and gravity that has reshaped theoretical physics and generated tools used well beyond its original setting.",
        "attribution": "Maldacena made the conjecture explicit; Witten developed and clarified its implications. Polyakov's earlier work helped establish the conceptual ground, so credit requires care.",
        "maturity": "The duality has been tested and exploited in many theoretical settings over decades, though direct experimental confirmation of the proposed gravitational correspondence is unavailable.",
        "uncertainties": [
          "How much weight to give a profound theoretical framework whose physical realization remains unsettled."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Charles L. Bennett",
        "Lyman A. Page",
        "David N. Spergel"
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's precision map of the cosmic microwave background made precision cosmology a quantitative enterprise and constrained the universe's age, composition, and history.",
        "attribution": "The named leaders represent crucial instrument, analysis, and theoretical contributions, but the result depended on a large mission team and shared foundations from earlier CMB work.",
        "maturity": "Independent measurements, especially from Planck, have tested and extended the cosmological picture WMAP established.",
        "uncertainties": [
          "The prize-worthy boundary between WMAP's specific advances and the broader progression of CMB cosmology."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Peter W. Shor",
        "Andrew M. Steane",
        "Alexei Kitaev"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed that quantum information can in principle survive noise, while topological codes connected protection to deep ideas in physics. This is foundational work with lasting influence.",
        "attribution": "Shor and Steane independently introduced landmark codes; Kitaev developed influential topological approaches. The distinct contributions are identifiable, though the field has many essential later contributors.",
        "maturity": "The theory is well established and experimental platforms now demonstrate error correction, but large-scale fault-tolerant machines remain an active goal.",
        "uncertainties": [
          "Whether the physical impact of quantum error correction has matured enough to judge its ultimate reach."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B035",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation offers an influential account of the universe's early expansion and of the origin of primordial structure, with a major legacy in cosmology.",
        "attribution": "Guth and Linde developed influential inflationary models; Mukhanov made a decisive contribution to the theory of perturbations that connect inflation to observable structure.",
        "maturity": "The framework has generated testable predictions and fits important observations, but the inflationary mechanism and its distinctive signatures have not been established.",
        "uncertainties": [
          "No unique inflation model has been confirmed, and primordial gravitational waves remain undetected."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Martin J. Rees",
        "Sandra M. Faber",
        "Simon D. M. White"
      ],
      "assessment": {
        "nobel_worthiness": "The dark matter and hierarchical structure picture explains how small early fluctuations can grow into galaxies and large-scale cosmic structure. It is central to modern cosmology.",
        "attribution": "These researchers made influential contributions to the observational and theoretical development of the picture, but its origins and validation span many groups and decades.",
        "maturity": "The structure-formation framework is extensively tested against astronomical observations and simulations, even as the identity of dark matter remains unknown.",
        "uncertainties": [
          "The broad discovery claim is difficult to assign to a small set of individuals.",
          "The nature of dark matter itself remains unresolved."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B044",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have transformed precision timekeeping and enable tests of fundamental physics through extraordinarily accurate frequency comparisons.",
        "attribution": "Katori and Ye made complementary, pioneering contributions to lattice-clock concepts and their experimental realization.",
        "maturity": "Independent laboratories have demonstrated clocks at remarkable and improving precision, with practical and scientific applications already emerging.",
        "uncertainties": [
          "Whether the field's greatest impact will be its measurement applications or future tests of fundamental physics."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B036",
      "proposed_laureates": [
        "Heino Falcke",
        "Sheperd S. Doeleman",
        "Ramesh Narayan"
      ],
      "assessment": {
        "nobel_worthiness": "The Event Horizon Telescope produced the first horizon-scale images of black holes, turning a longstanding prediction into an observational subject and opening a new regime of testing gravity.",
        "attribution": "Falcke helped frame the imaging target, Doeleman led key experimental and network efforts, and Narayan contributed influential theoretical interpretation. The result was inherently collaborative.",
        "maturity": "The images and subsequent observations are robust, but the scientific record is still developing and depends on complex imaging and model comparisons.",
        "uncertainties": [
          "How to divide credit fairly across the international collaboration and the many technical advances it required."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B045",
      "proposed_laureates": [
        "Francis Halzen",
        "Albrecht Karle",
        "Christian Spiering"
      ],
      "assessment": {
        "nobel_worthiness": "IceCube's detection of high-energy astrophysical neutrinos opened a new observational window on the universe and established neutrino astronomy as a field.",
        "attribution": "Halzen, Karle, and Spiering were major leaders in developing the detector and its scientific program, while the discovery depended on a large collaboration.",
        "maturity": "The astrophysical flux is established through multiple analyses, and source identifications are beginning to develop, though the population and production mechanisms remain under study.",
        "uncertainties": [
          "The sources responsible for most of the diffuse neutrino flux are not yet identified.",
          "Individual credit is difficult to separate from the collaboration's collective detector and analysis work."
        ]
      }
    }
  ]
